<?php
namespace App\\Http\\Controllers;use App\\Models\\{Product,Order,Payment};use Illuminate\\Http\\Request;use Illuminate\\Support\\Facades\\DB;use Illuminate\\Support\\Str;class CheckoutController extends Controller{public function create(){if(empty(session('cart',[])))return redirect()->route('cart.index');return view('checkout',['currency'=>session('currency','USD')]);}public function store(Request $r){$d=$r->validate(['shipping_name'=>'required|string|max:120','shipping_phone'=>'required|string|max:30','shipping_address'=>'required|string|max:500','shipping_city'=>'required|string|max:120','payment_method'=>'required|in:cash_on_delivery,bank_transfer,mobile_money','notes'=>'nullable|string|max:1000']);$cart=session('cart',[]);if(!$cart)return redirect()->route('cart.index');$currency=session('currency','USD');try{$order=DB::transaction(function()use($cart,$currency,$d,$r){$locked=[];$subtotal=0;foreach($cart as $id=>$line){$p=Product::whereKey($id)->lockForUpdate()->first();$qty=(int)$line['quantity'];if(!$p||!$p->is_active||$p->stock<$qty)throw new \\RuntimeException('Stock insuffisant pour '.($p?->name??'un produit'));$unit=(float)$p->price($currency);$subtotal+=$unit*$qty;$locked[]=[$p,$qty,$unit];}$o=Order::create(['user_id'=>$r->user()->id,'number'=>'CMD-'.strtoupper(Str::random(10)),'currency'=>$currency,'subtotal'=>$subtotal,'shipping_fee'=>0,'total'=>$subtotal,'status'=>'pending','payment_status'=>'pending','payment_method'=>$d['payment_method'],'shipping_name'=>$d['shipping_name'],'shipping_phone'=>$d['shipping_phone'],'shipping_address'=>$d['shipping_address'],'shipping_city'=>$d['shipping_city'],'notes'=>$d['notes']??null]);foreach($locked as [$p,$qty,$unit]){$o->items()->create(['product_id'=>$p->id,'product_name'=>$p->name,'unit_price'=>$unit,'quantity'=>$qty,'line_total'=>$unit*$qty]);$p->decrement('stock',$qty);}Payment::create(['order_id'=>$o->id,'method'=>$d['payment_method'],'amount'=>$subtotal,'currency'=>$currency,'status'=>'pending','notes'=>'Paiement à confirmer manuellement par un administrateur.']);return $o;});}catch(\\RuntimeException $e){return back()->withErrors(['stock'=>$e->getMessage()])->withInput();}session()->forget('cart');return redirect()->route('account.order',$order)->with('success','Commande enregistrée. Paiement à confirmer.');}}
